85:     pub fn seal_task(
86:         &mut self,
87:         id: &str,
88:         owner: &str,
89:         parent: Option<&str>,
90:         parent_artifact_sha256: Option<&str>,
91:         payload: &Value,
92:     ) -> Result<String, String> {
93:         if id.is_empty() || owner.is_empty() || self.tasks.contains_key(id) {
94:             return Err("invalid or duplicate task identity".into());
95:         }
96:         if let Some(parent_id) = parent {
97:             let prior = self.tasks.get(parent_id).ok_or("unknown parent task")?;
98:             if prior.state != TaskState::Completed {
99:                 return Err("parent task has not completed".into());
100:             }
101:             if prior.artifact_sha256.as_deref() != parent_artifact_sha256 {
102:                 return Err("parent artifact hash does not match completed task".into());
103:             }
104:         } else if parent_artifact_sha256.is_some() {
105:             return Err("root task cannot claim a parent artifact".into());
106:         }
107:         let plaintext = serde_json::to_vec(payload).map_err(|e| e.to_string())?;
108:         let key: [u8; 32] = fresh();
109:         let nonce: [u8; 12] = fresh();
110:         let wrap_nonce: [u8; 12] = fresh();
111:         let entropy: [u8; 32] = fresh();
112:         let aad = format!("task:{id}:{owner}:{}", parent.unwrap_or(""));
113:         let ciphertext = cipher(&key)
114:             .encrypt(
115:                 Nonce::from_slice(&nonce),
116:                 Payload {
117:                     msg: &plaintext,
118:                     aad: aad.as_bytes(),
119:                 },
120:             )
121:             .map_err(|_| "task encryption failed")?;
122:         let wrapped_key = cipher(&self.master)
123:             .encrypt(
124:                 Nonce::from_slice(&wrap_nonce),
125:                 Payload {
126:                     msg: &key,
127:                     aad: aad.as_bytes(),
128:                 },
129:             )
130:             .map_err(|_| "task key wrapping failed")?;
131:         let mut checksum_input = Vec::new();
132:         checksum_input.extend_from_slice(b"hive-task-v1\0");
133:         checksum_input.extend_from_slice(&entropy);
134:         checksum_input.extend_from_slice(aad.as_bytes());
135:         checksum_input.extend_from_slice(&nonce);
136:         checksum_input.extend_from_slice(&ciphertext);
137:         let checksum = sha(&checksum_input);
138:         self.tasks.insert(
139:             id.into(),
140:             Task {
141:                 owner: owner.into(),
142:                 parent: parent.map(str::to_owned),
143:                 parent_artifact_sha256: parent_artifact_sha256.map(str::to_owned),
144:                 checksum: checksum.clone(),
145:                 entropy,
146:                 nonce,
147:                 ciphertext,
148:                 wrap_nonce,
149:                 wrapped_key,
150:                 state: TaskState::Sealed,
151:                 artifact_sha256: None,
152:             },
153:         );
154:         Ok(checksum)
155:     }
