157:     pub fn open_task(
158:         &mut self,
159:         id: &str,
160:         requester: &str,
161:         current_parent_hash: Option<&str>,
162:     ) -> Result<Value, String> {
163:         let task = self.tasks.get_mut(id).ok_or("unknown task")?;
164:         if task.owner != requester || task.state != TaskState::Sealed {
165:             return Err("task owner or state denied".into());
166:         }
167:         if task.parent_artifact_sha256.as_deref() != current_parent_hash {
168:             return Err("parent artifact changed before dispatch".into());
169:         }
170:         let aad = format!(
171:             "task:{id}:{requester}:{}",
172:             task.parent.as_deref().unwrap_or("")
173:         );
174:         let mut checksum_input = Vec::new();
175:         checksum_input.extend_from_slice(b"hive-task-v1\0");
176:         checksum_input.extend_from_slice(&task.entropy);
177:         checksum_input.extend_from_slice(aad.as_bytes());
178:         checksum_input.extend_from_slice(&task.nonce);
179:         checksum_input.extend_from_slice(&task.ciphertext);
180:         if sha(&checksum_input) != task.checksum {
181:             return Err("task snapshot checksum mismatch".into());
182:         }
183:         let key = cipher(&self.master)
184:             .decrypt(
185:                 Nonce::from_slice(&task.wrap_nonce),
186:                 Payload {
187:                     msg: &task.wrapped_key,
188:                     aad: aad.as_bytes(),
189:                 },
190:             )
191:             .map_err(|_| "task key unwrap failed")?;
192:         let bytes = cipher(key.as_slice().try_into().map_err(|_| "bad task key")?)
193:             .decrypt(
194:                 Nonce::from_slice(&task.nonce),
195:                 Payload {
196:                     msg: &task.ciphertext,
197:                     aad: aad.as_bytes(),
198:                 },
199:             )
200:             .map_err(|_| "task snapshot authentication failed")?;
201:         task.state = TaskState::Opened;
202:         serde_json::from_slice(&bytes).map_err(|e| e.to_string())
203:     }
