311:     pub fn open_peer(&self, envelope: &Value, requester: &str) -> Result<Vec<u8>, String> {
312:         let field = |name| {
313:             envelope
314:                 .get(name)
315:                 .and_then(Value::as_str)
316:                 .ok_or(format!("missing {name}"))
317:         };
318:         let source = field("source")?;
319:         let destination = field("destination")?;
320:         let task_id = field("task_id")?;
321:         let grant_id = field("grant_id")?;
322:         if requester != destination {
323:             return Err("peer receiver denied".into());
324:         }
325:         let grant = self.channel(source, destination, task_id, grant_id)?;
326:         let nonce = hex::decode(field("nonce")?).map_err(|_| "bad peer nonce")?;
327:         let ciphertext = hex::decode(field("ciphertext")?).map_err(|_| "bad peer ciphertext")?;
328:         if nonce.len() != 12 {
329:             return Err("bad peer nonce length".into());
330:         }
331:         let aad = format!("peer:{source}:{destination}:{task_id}:{grant_id}");
332:         cipher(&grant.key)
333:             .decrypt(
334:                 Nonce::from_slice(&nonce),
335:                 Payload {
